package com.quincaisoft.tenders.application;import com.quincaisoft.tenders.api.*;import com.quincaisoft.tenders.infrastructure.*;import com.quincaisoft.tenders.domain.TenderRules;import com.quincaisoft.purchasing.api.PayablesService;import com.quincaisoft.sales.api.SalesService;import com.quincaisoft.customeraccounts.api.CustomerService;import com.quincaisoft.finance.api.FinanceService;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.nio.charset.StandardCharsets;
@Service public class DefaultSettlementService implements SettlementService{
 private final EntityManager em;private final ScopedTransactions tx;private final FinanceService finance;private final PayablesService payables;private final TenderService cash;private final BankService bank;private final SalesService sales;private final CustomerService customers;private final TenderOperations ops;
 public DefaultSettlementService(EntityManager em,ScopedTransactions tx,FinanceService finance,PayablesService payables,TenderService cash,BankService bank,SalesService sales,CustomerService customers,JsonMapper json){this.em=em;this.tx=tx;this.finance=finance;this.payables=payables;this.cash=cash;this.bank=bank;this.sales=sales;this.customers=customers;ops=new TenderOperations(em,json);}
 private Settlement view(SettlementEntity r){return new Settlement(r.id,r.kind,r.partyId,r.sourceId,r.relatedId,""+r.amountXaf,r.businessDate,r.bankEvidenceId,r.cashFactId,r.journalId);}
 public Settlement get(UUID id){return tx.execute(()->{var s=TenantContext.current();var r=em.find(SettlementEntity.class,new SettlementEntity.Key(s.tenantId(),s.companyId(),id));if(r==null)throw new NoSuchElementException("Scoped settlement not found");return view(r);});}
 public List<Settlement> list(){return tx.execute(()->em.createQuery("select r from SettlementEntity r order by r.businessDate desc,r.id",SettlementEntity.class).setMaxResults(500).getResultList().stream().map(this::view).toList());}
 private Settlement execute(Payment p,String kind,String debit,String credit,boolean incoming,java.util.function.Consumer<SettlementEntity> ledger){DefaultBankService.reason(p.reason());long amount=TenderRules.amount(p.amountXaf(),false);if(p.funding()==null||(p.funding().cashSessionId()==null)==(p.funding().bankEvidenceId()==null))throw new IllegalArgumentException("Choose exactly one cash session or approved bank evidence");return tx.execute(()->ops.once(p.operationId(),kind+"|"+p,kind,Settlement.class,()->{finance.requireOpenPeriod(p.businessDate());var s=TenantContext.current();var r=new SettlementEntity();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.kind=kind;r.partyId=p.partyId();r.sourceId=p.sourceId();r.businessDate=p.businessDate();r.amountXaf=amount;r.reason=p.reason();r.bankEvidenceId=p.funding().bankEvidenceId();
 if(r.bankEvidenceId!=null)bank.consume(r.bankEvidenceId,r.id,r.businessDate,amount,incoming?"IN":"OUT");
 ledger.accept(r);
 if(p.funding().cashSessionId()!=null){if(incoming||!Set.of("SUPPLIER_PAYMENT","SUPPLIER_ADVANCE").contains(kind))throw new IllegalArgumentException("Use the dedicated cash workflow for this source");UUID child=UUID.nameUUIDFromBytes(("settlement-cash:"+p.operationId()).getBytes(StandardCharsets.UTF_8));var fact=cash.supplierDisbursement(new TenderService.SupplierCash(child,r.id,p.funding().cashSessionId(),r.businessDate,""+amount,kind,p.reason()));r.cashFactId=fact.id();r.journalId=fact.journalId();}else r.journalId=finance.post(r.id,p.operationId(),r.businessDate,kind,List.of(new FinanceService.Entry(debit,amount,0),new FinanceService.Entry(credit,0,amount)));
 em.persist(r);em.flush();return view(r);},Settlement::id));}
 public Settlement supplierPayment(Payment p){return execute(p,"SUPPLIER_PAYMENT","ACCOUNTS_PAYABLE","BANK_CONTROL",false,r->payables.applyPayment(p.sourceId(),p.partyId(),r.amountXaf));}
 public Settlement supplierAdvance(Payment p){return execute(p,"SUPPLIER_ADVANCE","SUPPLIER_ADVANCES","BANK_CONTROL",false,r->{r.relatedId=r.id;payables.createAdvance(r.id,p.partyId(),r.amountXaf);});}
 public Settlement bankReceipt(Payment p){return execute(p,"BANK_RECEIPT","BANK_CONTROL","ACCOUNTS_RECEIVABLE",true,r->{customers.requireEligible(p.partyId());var sale=sales.get(p.sourceId());if(!sale.status().equals("POSTED")||!Objects.equals(sale.customerId(),p.partyId()))throw new IllegalArgumentException("Posted sale for same customer required");finance.applyReceipt(p.sourceId(),r.amountXaf);});}
 public Settlement bankDeposit(Payment p){return execute(p,"BANK_DEPOSIT","BANK_CONTROL","CUSTOMER_ADVANCES",true,r->{customers.requireEligible(p.partyId());var d=new DepositBalanceEntity();d.tenantId=r.tenantId;d.companyId=r.companyId;d.branchId=r.branchId;d.id=r.id;d.customerId=p.partyId();d.originalXaf=r.amountXaf;d.fundingKind="BANK";em.persist(d);r.relatedId=d.id;});}
 public Settlement bankExpense(Payment p){if(p.sourceId()==null)throw new IllegalArgumentException("Approved expense identity required");return execute(p,"BANK_EXPENSE","OPERATING_EXPENSE","BANK_CONTROL",false,r->{});}
 public Settlement allocateAdvance(Allocate p){DefaultBankService.reason(p.reason());long n=TenderRules.amount(p.amountXaf(),false);return tx.execute(()->ops.once(p.operationId(),"ADVANCE_ALLOCATION|"+p,"AdvanceAllocated",Settlement.class,()->{finance.requireOpenPeriod(p.businessDate());payables.allocateAdvance(p.advanceId(),p.invoiceId(),n);var s=TenantContext.current();var r=new SettlementEntity();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.kind="ADVANCE_ALLOCATION";r.sourceId=p.invoiceId();r.relatedId=p.advanceId();r.amountXaf=n;r.businessDate=p.businessDate();r.reason=p.reason();r.journalId=finance.post(r.id,p.operationId(),p.businessDate(),r.kind,List.of(new FinanceService.Entry("ACCOUNTS_PAYABLE",n,0),new FinanceService.Entry("SUPPLIER_ADVANCES",0,n)));em.persist(r);em.flush();return view(r);},Settlement::id));}
}